export function SkillIcon({ icon, className = "" }: { icon: SkillIconKey; className?: string }) {
  const glyph = glyphs[icon];
  return glyph.stroke ? (
    <svg viewBox="0 0 24 24" aria-hidden className={className} fill="none" stroke="currentColor" strokeWidth={glyph.strokeWidth ?? 2} strokeLinecap="round" strokeLinejoin="round">
      <path d={glyph.d} />
    </svg>
  ) : (
    <svg viewBox={glyph.viewBox ?? "0 0 24 24"} aria-hidden className={className} fill="currentColor">
      <path d={glyph.d} />
    </svg>
  );
}
